class PaymentServiceTest extends TestCase
{
    public function testPaymentSuccess(): void
    {
        $gateway = $this->createMock(GatewayInterface::class);
        $gateway->method('charge')
            ->willReturn(true);

        $service = new PaymentService($gateway);
        $this->assertTrue($service->pay(100));
    }
}
```

### Мокаем time

```php
class OrderTest extends TestCase
{
    public function testExpiredOrder(): void
    {
        frozenTime('2024-01-01'); // для determinism

        $order = Order::create();
        $this->assertTrue($order->isExpired());
    }
}
```

